+++ b/drivers/crypto/ccp/ccp-ops.c
@@ -1516,6 +1516,9 @@ ccp_run_sha_cmd(struct ccp_cmd_queue *cmd_q, struct ccp_cmd *cmd)
 	if (!sha->ctx)
 		return -EINVAL;

+	if (sha->ctx_len < sb_count * CCP_SB_BYTES)
+		return -EINVAL;
+
 	if (!sha->final && (sha->src_len & (block_size - 1)))
 		return -EINVAL;

